/** Version of the committed `.frontal/` contract. Bump when generated output changes shape. */
export const CONTRACT_VERSION = 1 as const;

/**
 * Version of the generator's output, written into every generated header and
 * `version.json`. It is independent of the CLI release: it changes only when
 * the generated files change, so upgrading the CLI does not make committed
 * files look stale. Bump it whenever generator output changes.
 */
export const GENERATOR_VERSION = "3.0.0" as const;

/** Format tag written into `ontology.json`. */
export const ONTOLOGY_FORMAT = "frontal.ontology/v2" as const;

/**
 * First @frontal-labs/sdk release with the generic `createFrontalClient<T>`
 * factory that generated clients import. Published 2.0.0 does not have it.
 */
export const SDK_MIN_VERSION = "2.1.0";
export const SDK_RANGE = `>=${SDK_MIN_VERSION} <3.0.0`;

/** Path of the object-type list as the SDK's ontology namespace expects it. */
export const OBJECT_TYPES_SDK_PATH = "/ontology/objects/object-types";

/** Where the object types come from, recorded in `ontology.json`. */
export const OBJECT_TYPES_SOURCE = {
  endpoint: "/v1/ontology/objects/object-types",
  service: "ontology/objects",
} as const;

export const GENERATED_BANNER =
  "AUTO-GENERATED BY FRONTAL CLI. DO NOT EDIT MANUALLY.";

/** Generated files inside `.frontal/`, keyed by role. */
export const ONTOLOGY_FILES = {
  client: "client.ts",
  document: "ontology.json",
  types: "ontology.d.ts",
  version: "version.json",
} as const;

export type OntologyFileKey = keyof typeof ONTOLOGY_FILES;

/**
 * Write order. `document` (ontology.json) is last: it is the commit marker
 * that `check` and `status` read, so an interrupted sync never looks complete.
 */
export const WRITE_ORDER: readonly OntologyFileKey[] = [
  "types",
  "client",
  "version",
  "document",
];

/** Entity names that would collide with the SDK's own `ontology` namespaces. */
export const RESERVED_ENTITY_NAMES: readonly string[] = [
  "engine",
  "objects",
  "relationships",
  "schemas",
  "versions",
  "validation",
  "transformations",
  "reasoning",
  "rollouts",
  "rollups",
  "extract",
  "events",
];

/**
 * Member names the generated record type already owns. Relations and fields
 * cannot take them, because the object id is always exposed as `id`.
 */
export const RESERVED_MEMBER_NAMES: readonly string[] = ["id"];
